class QualifiedSupervisor(ABC):
    @abstractmethod
    def admit(self, *, request_json, decision_json, guard_contract_json,
              resources_json, runtime_inventory_json, artifacts, bindings):
        """Validate actual pinned trusted runtime, loaded objects and synthetic inputs.

        Verify ROOT decision bytes against pins provided by trusted caller, the
        prior independent review, protected stable root, exact store operations,
        one real external watchdog and scoped audit latch. No bool-alone release.
        Reject observations, unknown source/modules/maps or missing capabilities.
        Runtime/native trust is explicit; no universal syscall detection claim.
        """
        raise NotImplementedError('REVIEWED_COOPERATIVE_SCIENCE_BOOTSTRAP_REQUIRED')

    @abstractmethod
    def checkpoint(self, phase, context):
        """Bound identity, unit, monotonic deadlines, counters and sticky latch."""
        raise NotImplementedError('REVIEWED_COOPERATIVE_CHECKPOINT_REQUIRED')

    @abstractmethod
    def process_identity(self):
        """Verified live POSIX pid/start_ticks, bound to actual parent watchdog."""
        raise NotImplementedError('PROCESS_IDENTITY_REQUIRED')

    @abstractmethod
    def terminal_audit(self, *, context):
        """Return scoped receipt accepted by validate_terminal; never native zero."""
        raise NotImplementedError('SCOPED_RECEIPT_REQUIRED')

def _audit(self, event, args):
    reason = None
    target = str(args[:1])[:500]
    if event.startswith(('socket.','subprocess.','os.spawn')) or event in (
        'os.system','os.posix_spawn','os.fork','os.forkpty','os.remove','os.rmdir',
        'os.rename','os.mkdir','os.link','os.symlink','os.truncate','sys.addaudithook'):
        reason='OPERATION_OUTSIDE_STDLIB_QUALIFICATION'
        if event.startswith('socket.'):
            self.network_denials += 1
    if event == 'ctypes.dlopen':
        reason='NATIVE_DYNAMIC_LOAD_NOT_ALLOWED_IN_STDLIB_SCOPE'
    if event == 'open':
        target,mode,flags=args
        writing=(isinstance(mode,str) and any(x in mode for x in 'wax+')) or (
            isinstance(flags,int) and bool(flags & (os.O_WRONLY|os.O_RDWR|os.O_CREAT|os.O_TRUNC|os.O_APPEND)))
        if isinstance(target,int):
            if target not in self.output_fds:
                reason='UNREGISTERED_FILE_DESCRIPTOR'
        elif writing:
            reason='NO_PATH_WRITES_AFTER_HOOK'
        else:
            name=os.path.normpath(str(target))
            if name not in self.read_pins:
                self.read_denials += 1
                reason='UNPINNED_READ'
            self.read_events += 1
    if reason:
        self.latch.deny(event,target,reason=reason)

def _flush_dir(self):
    fd = os.open(self.root, os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)

def _path(self, kind, key, suffix):
    if kind not in ('background', 'node') or type(key) is not str or len(key) != 64 or any(c not in '0123456789abcdef' for c in key):
        raise StoreError('INVALID_STORE_IDENTITY')
    if suffix not in ('claim', 'result', 'failure'):
        raise StoreError('INVALID_STORE_ARTIFACT')
    return self.root / (kind + '_' + key + '.' + suffix + '.json')

def _read(self, path):
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
    try:
        with os.fdopen(fd, 'rb', closefd=False) as stream:
            raw = stream.read(self.cap + 1)
        if not raw or len(raw) > self.cap:
            raise StoreError('RECORD_SIZE')
        return raw, json.loads(raw, object_pairs_hook=_pairs, parse_constant=_bad_constant)
    finally:
        os.close(fd)

def _exclusive_write(self, path, raw):
    if type(raw) is not bytes or not raw or len(raw) > self.cap:
        raise StoreError('RECORD_SIZE')
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
    try:
        with os.fdopen(fd, 'wb', closefd=False) as stream:
            stream.write(raw); stream.flush(); os.fsync(fd)
    finally:
        os.close(fd)
    self._flush_dir()

def _publish(self, destination, record):
    raw = _canonical(record)
    temporary = self.root / ('.pending_' + uuid.uuid4().hex)
    self._exclusive_write(temporary, raw)
    # link is an atomic no-overwrite publication of already fsynced bytes.
    os.link(temporary, destination, follow_symlinks=False)
    self._flush_dir()
    # Keep the temporary hardlink for explicit recovery; no automatic cleanup.
    return _sha(raw)

def capture(process, work_deadline, caps):
    selector = selectors.DefaultSelector()
    buffers = {name:bytearray() for name in ('stdout','stderr')}
    try:
        for name in buffers:
            stream = getattr(process,name)
            os.set_blocking(stream.fileno(),False)
            selector.register(stream,selectors.EVENT_READ,name)
        while selector.get_map() or process.poll() is None:
            if time.monotonic() >= work_deadline:
                return buffers, 'WORK_DEADLINE'
            for key,_ in selector.select(min(.05,max(0,work_deadline-time.monotonic()))):
                chunk = os.read(key.fileobj.fileno(),4096)
                if not chunk:
                    selector.unregister(key.fileobj)
                    continue
                room = caps[key.data] - len(buffers[key.data])
                buffers[key.data].extend(chunk[:max(0,room)])
                if len(chunk) > room:
                    return buffers, 'OUTPUT_OVERFLOW'
        return buffers, 'EXITED'

except BaseException as exc:
    error=bounded_error(exc)
finally:
    if process is not None and not reaped:
        try:
            if process.poll() is None:
                need(pidfd is not None and expected_child is not None,'UNBOUND_CHILD_CLEANUP_UNCERTAIN')
                kill_exact(pidfd,expected_child);killed=True
            remaining=total-time.monotonic()
            need(remaining>0,'REAP_BUDGET_EXHAUSTED')
            process.wait(timeout=remaining);reaped=True
        except BaseException as exc:
            status='PROCESS_STATE_UNCERTAIN_NO_RETRY';error=bounded_error(exc)
    if pidfd is not None:
        os.close(pidfd)
    if process is not None:
        for name in ('stdin','stdout','stderr'):
            stream=getattr(process,name)
            if stream is not None and not stream.closed:
                stream.close()
if not reaped or time.monotonic() >= total:
    status='PROCESS_OR_FINALIZATION_INCOMPLETE_NO_RETRY'

